  commitment:{academicExample:'Long-term commitment is needed to improve public health.',academicTranslation:'改善公共卫生需要长期投入。'},
  confirm:{academicExample:'The second survey confirmed the original findings.',academicTranslation:'第二项调查证实了最初的发现。'},
  confirmation:{academicExample:'Further research is needed for confirmation of this result.',academicTranslation:'这一结果需要进一步研究来确认。'},
